// Dashboard tests
test('dashboard returns empty counts for no invoices', () => {
  const result = dashboard([], '2026-10-31');
  assert.equal(result.counts.draft, 0);
  assert.equal(result.counts.issued, 0);
  assert.equal(result.counts.partially_paid, 0);
  assert.equal(result.counts.paid, 0);
});

test('dashboard counts invoices by status', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued2 = issueInvoice(inv2.value, []).value;

  let inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  inv3 = issueInvoice(inv3.value, ['INV-2026-0001']).value;
  const totals3 = invoiceTotals(inv3);
  inv3 = recordPayment(inv3, { amount: Math.floor(totals3.total / 2), date: '2026-10-04' }).value;

  let inv4 = createInvoice({
    customerId: 'C-004',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  inv4 = issueInvoice(inv4.value, ['INV-2026-0002']).value;
  const totals4 = invoiceTotals(inv4);
  inv4 = recordPayment(inv4, { amount: totals4.total, date: '2026-10-06' }).value;

  const result = dashboard([inv1.value, issued2, inv3, inv4], '2026-10-31');
  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.partially_paid, 1);
  assert.equal(result.counts.paid, 1);
});

test('dashboard calculates outstanding amount', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(inv1.value, []).value;
  const totals1 = invoiceTotals(issued1);

  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  inv2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;
  const totals2 = invoiceTotals(inv2);
  const payment2 = Math.floor(totals2.total / 2);
  inv2 = recordPayment(inv2, { amount: payment2, date: '2026-10-03' }).value;

  const result = dashboard([issued1, inv2], '2026-10-31');
  const expected = totals1.total + (totals2.total - payment2);
  assert.equal(result.outstanding, expected);
});

test('dashboard includes overdue info', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(inv1.value, []).value;
  const totals1 = invoiceTotals(issued1);

  const result = dashboard([issued1], '2026-10-31');
  assert.equal(result.overdue.count, 1);
  assert.equal(result.overdue.amount, totals1.total);
});

test('dashboard excludes non-overdue from overdue count', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  const issued = issueInvoice(inv.value, []).value;

  const result = dashboard([issued], '2026-10-20');
  assert.equal(result.overdue.count, 0);
  assert.equal(result.overdue.amount, 0);
});

test('dashboard identifies top customers by amount due', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(inv1.value, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0002']).value;

  const result = dashboard([issued1, issued2, issued3], '2026-10-31');
  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C-001');
  assert.equal(result.topCustomers[1].customerId, 'C-002');
  assert.equal(result.topCustomers[2].customerId, 'C-003');
});

test('dashboard returns only top 3 customers', () => {
  const invoices = [];
  for (let i = 1; i <= 5; i++) {
    const inv = createInvoice({
      customerId: `C-${i.toString().padStart(3, '0')}`,
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: i }],
    });
    const issued = issueInvoice(inv.value, invoices.map((x) => x.number)).value;
    invoices.push(issued);
  }

  const result = dashboard(invoices, '2026-10-31');
  assert.equal(result.topCustomers.length, 3);
});

test('dashboard sorts top customers by amount due descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(inv1.value, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0002']).value;

  const result = dashboard([issued1, issued2, issued3], '2026-10-31');
  assert(result.topCustomers[0].due > result.topCustomers[1].due);
  assert(result.topCustomers[1].due > result.topCustomers[2].due);
});

